def transform(grid):
    out=[row[:] for row in grid]
    R,C=len(grid),len(grid[0])
    for r in range(R):
        for c in range(C):
            if grid[r][c]==2:
                # markers embedded in a color-3 object mark the center of a 3x3 patch
                if any(0<=r+dr<R and 0<=c+dc<C and grid[r+dr][c+dc]==3
                       for dr in (-1,0,1) for dc in (-1,0,1)):
                    # only markers within an object's 3-region are active
                    if grid[r][c] != 3: # markers stay 2; identify neighbor presence but require marker located within rectangle interior
                        # neighboring 3s on opposing sides/diagonal indicate insertion into a block
                        if sum(0<=r+dr<R and 0<=c+dc<C and grid[r+dr][c+dc]==3 for dr in (-1,0,1) for dc in (-1,0,1)) >= 3:
                            for dr in (-1,0,1):
                                for dc in (-1,0,1):
                                    rr,cc=r+dr,c+dc
                                    if 0<=rr<R and 0<=cc<C and grid[rr][cc]==3: out[rr][cc]=1
    return out
PY

